// Package review — see env.go for package-level rationale.
//
// fix_headless.go provides the terminal-dashboard apply path: a per-finding
// headless Fixer seam and the apply func the TUI model invokes when the user
// presses Enter on selected findings.
//
// "Headless" is load-bearing — the fixer must run without owning the terminal,
// because the Bubble Tea dashboard already does. The interactive
// agentlaunch.LaunchFixAgent inherits stdio and would fight the TUI for the TTY.
//
// Visibility is per-finding and semantic, not a transcript: each fix returns a
// short natural-language SUMMARY of what changed; the apply layer pairs it with
// the finding's actual diff + line counts (computed from git) so the dashboard
// can show "added `if b == 0 { return 0 }` before the divide · +3 −1" with the
// full diff one keystroke away.
//
// This path is the bare-terminal surface only. In an agent session the host
// agent performs the fix in-conversation; there is no dashboard and this apply
// func is never wired.
package review

import (
	"context"
	"fmt"
	"sort"
	"strconv"
	"strings"

	tea "charm.land/bubbletea/v2"
)

// Fixer applies a fix for ONE finding without owning the terminal, and returns a
// short natural-language summary of what it changed. Implemented per-agent
// (claudecode.NewFixer) and injected via Deps.FixerFor to avoid the
// review → agent import cycle.
type Fixer interface {
	// FixOne edits the files for one finding and returns a summary of what it
	// changed (including the key snippet added). Success is false when the fixer
	// could not complete; err is non-nil when it could not start.
	FixOne(ctx context.Context, finding Finding, worktreeRoot string) (FixOutcome, error)
}

// FixOutcome is the fixer's self-reported result for one finding.
type FixOutcome struct {
	Summary string
	Success bool
}

// buildApplyFunc returns the model's per-finding apply func: given ONE selected
// finding, it returns a tea.Cmd that runs the headless fixer on it and yields a
// fixOneDoneMsg with the semantic summary + diff + counts + re-verified status.
// The model drives the selected set through this one finding at a time, so each
// finding gets its own attributed diff. Returns nil when no fixer is available
// (Enter then just exits).
func buildApplyFunc(ctx context.Context, fixer Fixer, verifier VerifyProvider, worktreeRoot, scopeBaseRef string) func(Finding) tea.Cmd {
	if fixer == nil {
		return nil
	}
	return func(f Finding) tea.Cmd {
		return func() tea.Msg {
			return fixOneDoneMsg{id: f.ID, result: applyOneFix(ctx, fixer, verifier, worktreeRoot, scopeBaseRef, f)}
		}
	}
}

// applyOneFix runs the fixer on one finding and classifies the result. It snaps
// the git diff before/after to attribute the change (diff text + ± counts) to
// this finding, then re-verifies: a finding that no longer reproduces is fixed;
// one that still reproduces needs a human; a fixer failure is failed.
//
// Known minor imperfection: when two findings edit the same file, the second's
// diff/counts include the first's hunks for that file. Acceptable for v1 — the
// fixer's SUMMARY still describes only what it just did.
func applyOneFix(ctx context.Context, fixer Fixer, verifier VerifyProvider, worktreeRoot, scopeBaseRef string, f Finding) fixResult {
	before := gitNumstat(ctx, worktreeRoot, scopeBaseRef)
	outcome, err := fixer.FixOne(ctx, f, worktreeRoot)
	if err != nil || !outcome.Success {
		return fixResult{status: fixStatusFailed}
	}
	after := gitNumstat(ctx, worktreeRoot, scopeBaseRef)
	files, added, removed := numstatDelta(before, after)
	diff := ""
	if len(files) > 0 {
		diff = gitDiffFiles(ctx, worktreeRoot, scopeBaseRef, files)
	}
	status := fixStatusFixed
	if verifier != nil {
		postFixDiff := buildReviewFullDiff(ctx, worktreeRoot, scopeBaseRef)
		for _, stillThere := range verifyFindings(ctx, verifier, []Finding{f}, postFixDiff) {
			if stillThere.ID == f.ID {
				status = fixStatusNeedsHuman
			}
		}
	}
	return fixResult{summary: outcome.Summary, diff: diff, files: files, added: added, removed: removed, status: status}
}

// ComposeFixPrompt builds the single-finding fix instruction, including the
// SUMMARY contract the fixer must satisfy. Exported so per-agent fixers
// (claudecode) compose an identical prompt; the SUMMARY line is parsed back by
// ParseFixSummary.
func ComposeFixPrompt(f Finding) string {
	loc := f.File
	if f.Line > 0 {
		loc = fmt.Sprintf("%s:%d", f.File, f.Line)
	}
	var b strings.Builder
	b.WriteString("Fix this one review finding by editing the files directly. ")
	b.WriteString("Keep the change minimal and targeted — do not rewrite unrelated code.\n\n")
	fmt.Fprintf(&b, "[%s] %s (%s)\n", strings.ToUpper(string(f.Severity)), f.Title, loc)
	if f.Detail != "" {
		fmt.Fprintf(&b, "%s\n", f.Detail)
	}
	if f.Suggestion != "" {
		fmt.Fprintf(&b, "Suggested fix: %s\n", f.Suggestion)
	}
	b.WriteString("\nWhen done, end your reply with exactly one line:\n")
	b.WriteString("SUMMARY: <one sentence describing what you changed, naming the key snippet you added>\n")
	return b.String()
}

// ParseFixSummary extracts the trailing `SUMMARY:` line from a fixer's output.
// Returns "" when none is present (the model falls back to a generic label).
func ParseFixSummary(output string) string {
	lines := strings.Split(output, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if rest, ok := strings.CutPrefix(strings.TrimSpace(lines[i]), "SUMMARY:"); ok {
			return strings.TrimSpace(rest)
		}
	}
	return ""
}

// gitNumstat returns per-file (added, removed) line counts for the two-dot diff
// against base. Binary files (numstat "-") count as 0.
func gitNumstat(ctx context.Context, worktreeRoot, base string) map[string][2]int {
	res := map[string][2]int{}
	out, err := runGit(ctx, worktreeRoot, "diff", "--numstat", base)
	if err != nil {
		return res
	}
	for _, line := range strings.Split(out, "\n") {
		fields := strings.Split(line, "\t")
		if len(fields) < 3 {
			continue
		}
		res[fields[2]] = [2]int{atoiOrZero(fields[0]), atoiOrZero(fields[1])} // "-" (binary) → 0
	}
	return res
}

// atoiOrZero parses s, returning 0 on error (numstat uses "-" for binary files).
func atoiOrZero(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return n
}

// numstatDelta returns the files whose counts changed between before and after,
// plus the total added/removed delta across them (clamped at 0).
func numstatDelta(before, after map[string][2]int) (files []string, added, removed int) {
	for f, a := range after {
		b := before[f]
		if a == b {
			continue
		}
		files = append(files, f)
		added += max(0, a[0]-b[0])
		removed += max(0, a[1]-b[1])
	}
	sort.Strings(files)
	return files, added, removed
}

// gitDiffFiles returns the two-dot diff against base restricted to files.
func gitDiffFiles(ctx context.Context, worktreeRoot, base string, files []string) string {
	out, err := runGit(ctx, worktreeRoot, append([]string{"diff", base, "--"}, files...)...)
	if err != nil {
		return ""
	}
	return out
}

