package claudecode

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/review"
)

// NewFixer returns the headless per-finding Fixer for claude-code, used by the
// review dashboard's in-dashboard apply flow.
//
// FixOne runs `claude -p <prompt> --permission-mode acceptEdits` in the worktree.
// The -p (print) mode is non-interactive: claude never prompts for input, so it
// coexists with the Bubble Tea dashboard that owns the terminal. acceptEdits
// auto-accepts file edits (the fixer's core need) without granting broader tool
// access. The prompt (review.ComposeFixPrompt) instructs claude to end with a
// `SUMMARY:` line describing the change, which review.ParseFixSummary recovers
// for the dashboard's semantic summary. The interactive agentlaunch.LaunchFixAgent
// could not be reused here (inherits stdio, fights the terminal).
//
//nolint:ireturn // returns the review.Fixer interface by design (injection seam, mirrors NewReviewer)
func NewFixer() review.Fixer {
	return claudeFixer{}
}

type claudeFixer struct{}

func (claudeFixer) FixOne(ctx context.Context, finding review.Finding, worktreeRoot string) (review.FixOutcome, error) {
	cmd := exec.CommandContext(ctx, "claude", "-p", review.ComposeFixPrompt(finding), "--permission-mode", "acceptEdits")
	cmd.Dir = worktreeRoot
	cmd.Env = withoutReviewEnv(os.Environ())
	out, err := cmd.CombinedOutput()
	if err != nil {
		return review.FixOutcome{Success: false}, fmt.Errorf("claude fix run: %w (output: %s)", err, strings.TrimSpace(string(out)))
	}
	return review.FixOutcome{Summary: review.ParseFixSummary(string(out)), Success: true}, nil
}

// withoutReviewEnv strips the ENTIRE_REVIEW_* / ENTIRE_INVESTIGATE_* handshake
// vars so the fix session is not tagged as a review/investigate session by the
// lifecycle hooks (mirrors agentlaunch's env hygiene for fix sessions).
func withoutReviewEnv(env []string) []string {
	out := make([]string, 0, len(env))
	for _, kv := range env {
		if strings.HasPrefix(kv, "ENTIRE_REVIEW_") || strings.HasPrefix(kv, "ENTIRE_INVESTIGATE_") {
			continue
		}
		out = append(out, kv)
	}
	return out
}

