// fakeFixer records the finding it was asked to fix and returns a configurable
// outcome (or error).
type fakeFixer struct {
	outcome   FixOutcome
	err       error
	gotID     string
	callCount int
}

func (f *fakeFixer) FixOne(_ context.Context, finding Finding, _ string) (FixOutcome, error) {
	f.callCount++
	f.gotID = finding.ID
	return f.outcome, f.err
}

// verdictVerifier returns a fixed verdict per finding ID, modelling the post-fix
// re-verify: refuted → the issue is gone (fixed); confirmed → it still
// reproduces (needs-human).
type verdictVerifier map[string]Verdict

func (v verdictVerifier) Verify(_ context.Context, f Finding, _ string) (VerifyResult, error) {
	verdict, ok := v[f.ID]
	if !ok {
		verdict = VerdictConfirmed
	}
	return VerifyResult{Verdict: verdict}, nil
}

func TestApplyOneFix_ReVerifyGoneIsFixed(t *testing.T) {
	t.Parallel()
	// HIGH finding (skepticsFor(high) == 3, so verify runs); verifier refutes →
	// the issue is gone → fixed.
	f := Finding{ID: "gone", Severity: SeverityHigh, Title: "g"}
	fixer := &fakeFixer{outcome: FixOutcome{Summary: "added a guard", Success: true}}
	verifier := verdictVerifier{"gone": VerdictRefuted}

	res := applyOneFix(context.Background(), fixer, verifier, t.TempDir(), "HEAD", f)

	if res.status != fixStatusFixed {
		t.Errorf("status: got %q, want %q", res.status, fixStatusFixed)
	}
	if res.summary != "added a guard" {
		t.Errorf("summary: got %q", res.summary)
	}
	if fixer.callCount != 1 || fixer.gotID != "gone" {
		t.Errorf("fixer calls=%d id=%q, want 1/gone", fixer.callCount, fixer.gotID)
	}
}

func TestApplyOneFix_StillReproducesNeedsHuman(t *testing.T) {
	t.Parallel()
	f := Finding{ID: "stays", Severity: SeverityHigh, Title: "s"}
	fixer := &fakeFixer{outcome: FixOutcome{Success: true}}
	verifier := verdictVerifier{"stays": VerdictConfirmed}

	res := applyOneFix(context.Background(), fixer, verifier, t.TempDir(), "HEAD", f)

	if res.status != fixStatusNeedsHuman {
		t.Errorf("status: got %q, want %q", res.status, fixStatusNeedsHuman)
	}
}

