package review

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	agenttypes "github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

const localReviewManifestVersion = 1

// reviewTokenMaxDepth caps recursion when summing SubagentTokens. Subagent
// trees are shallow in practice (single-digit depth), so this is defensive
// insurance against a malformed/cyclic *agent.TokenUsage causing stack
// overflow during a review run.
const reviewTokenMaxDepth = 16

// agentTypeLookup resolves an agent.AgentType to its Agent implementation.
// Threaded as an explicit dependency through the hydration helpers so tests
// can inject a fake without mutating the package-level agent registry — and
// without parallel-test footguns from a shared mutable variable.
type agentTypeLookup func(agenttypes.AgentType) (agent.Agent, error)

// LocalReviewManifest records one local `entire review` invocation. It lets
// `entire review --fix <session-id>` use a single session id as the lookup
// handle while still loading sibling agent outputs from the same review run.
type LocalReviewManifest struct {
	Version         int              `json:"version"`
	WorktreePath    string           `json:"worktree_path"`
	CreatedAt       time.Time        `json:"created_at"`
	StartingSHA     string           `json:"starting_sha,omitempty"`
	Sources         []ManifestSource `json:"sources"`
	AggregateOutput string           `json:"aggregate_output,omitempty"`
	Findings        []Finding        `json:"findings,omitempty"`  // structured findings (PR #1, spec §4/§5a)
	Synthesis       string           `json:"synthesis,omitempty"` // one-paragraph verdict
}

// structureFindings runs the structuring pass over the run's agent narratives
// (spec §5a). Returns (nil, "") when no provider is configured or no agent
// produced output — review never hard-fails on structuring, and gating on a
// nil provider avoids triggering summary-provider resolution on runs where
// structuring cannot apply.
func structureFindings(
	ctx context.Context,
	provider PipelineProvider,
	summary reviewtypes.RunSummary,
	diffContext string,
) ([]Finding, string) {
	if provider == nil {
		return nil, ""
	}
	agents := make([]AgentOutput, 0, len(summary.AgentRuns))
	for _, run := range summary.AgentRuns {
		if out := agentRunOutput(run); out != "" {
			agents = append(agents, AgentOutput{Agent: run.Name, Output: out})
		}
	}
	if len(agents) == 0 {
		return nil, ""
	}
	rev, err := provider.Structure(ctx, StructureInput{Agents: agents, DiffContext: diffContext})
	if err != nil {
		return nil, ""
	}
	return rev.Findings, rev.Synthesis
}

// persistReviewFindingsOnState stashes the run's structured findings onto the
// matched review session state (as raw JSON) so the next commit's condensation
// carries them onto the checkpoint (spec §9). PR #1 attaches the full set to
// the first review session source (single-agent focus); per-agent splitting is
// a later concern. Best-effort: failures are logged, never fatal.
func persistReviewFindingsOnState(ctx context.Context, states []*session.State, manifest LocalReviewManifest) {
	if len(manifest.Findings) == 0 || len(manifest.Sources) == 0 {
		return
	}
	b, err := json.Marshal(manifest.Findings)
	if err != nil {
		logging.Debug(ctx, "marshal review findings for session state failed", slog.String("error", err.Error()))
		return
	}
	store, err := session.NewStateStore(ctx)
	if err != nil {
		logging.Debug(ctx, "open session store to persist findings failed", slog.String("error", err.Error()))
		return
	}
	wantID := manifest.Sources[0].SessionID
	for _, st := range states {
		if st == nil || st.SessionID != wantID {
			continue
		}
		st.ReviewFindingsJSON = b
		if saveErr := store.Save(ctx, st); saveErr != nil {
			logging.Debug(ctx, "persist review findings on session failed", slog.String("error", saveErr.Error()))
		}
		return
	}
}

// buildReviewDiffContext returns the in-scope file paths (one per line) followed
// by the unified-diff hunk headers, used by the structuring provider to resolve
// File and the enclosing symbol for stable IDs (spec §9). Best-effort: returns
// "" when there is no base ref or git errors (anchoring then degrades to
// Line=0 / the D3 fallback).
func buildReviewDiffContext(ctx context.Context, worktreeRoot, scopeBaseRef string) string {
	if scopeBaseRef == "" {
		return ""
	}
	// Base-vs-working-tree (two-dot) so uncommitted changes in scope are
	// included — the review scope is "commits unique to this branch + uncommitted".
	files, err := runGit(ctx, worktreeRoot, "diff", "--name-only", scopeBaseRef)
	if err != nil {
		return "" // best-effort: no diff context → anchoring degrades to Line=0 / D3
	}
	hunks, err := runGit(ctx, worktreeRoot, "diff", "--unified=0", scopeBaseRef)
	if err != nil {
		return strings.TrimSpace(files) // file list alone still helps File resolution
	}
	var b strings.Builder
	b.WriteString(strings.TrimSpace(files))
	for _, ln := range strings.Split(hunks, "\n") {
		if strings.HasPrefix(ln, "@@") {
			b.WriteString("\n")
			b.WriteString(ln)
		}
	}
	return strings.TrimSpace(b.String())
}

// buildReviewFullDiff returns the full unified diff WITH code (base vs working
// tree, so uncommitted changes are included), capped to keep verify prompts
// bounded. This is the verifier's code context (spec §7) — without it, skeptics
// judge blind and wrongly refute real findings.
func buildReviewFullDiff(ctx context.Context, worktreeRoot, scopeBaseRef string) string {
	if scopeBaseRef == "" {
		return ""
	}
	out, err := runGit(ctx, worktreeRoot, "diff", scopeBaseRef)
	if err != nil {
		return ""
	}
	const maxDiff = 16000
	if len(out) > maxDiff {
		return out[:maxDiff] + "\n…(diff truncated)…"
	}
	return out
}

type ManifestSource struct {
	SessionID string `json:"session_id"`
	Agent     string `json:"agent"`
	Label     string `json:"label"`
	Status    string `json:"status,omitempty"`
	Output    string `json:"output,omitempty"`
}

func buildLocalReviewManifestFromSummary(
	worktreeRoot string,
	headSHA string,
	summary reviewtypes.RunSummary,
	states []*session.State,
	aggregateOutput string,
) LocalReviewManifest {
	manifest := LocalReviewManifest{
		Version:         localReviewManifestVersion,
		WorktreePath:    worktreeRoot,
		CreatedAt:       summary.StartedAt,
		StartingSHA:     headSHA,
		AggregateOutput: strings.TrimSpace(aggregateOutput),
	}
	usedSessions := map[string]bool{}
	for _, run := range summary.AgentRuns {
		st := matchReviewSessionState(worktreeRoot, headSHA, summary.StartedAt, run.Name, states, usedSessions)
		if st == nil || st.SessionID == "" {
			continue
		}
		usedSessions[st.SessionID] = true
		manifest.Sources = append(manifest.Sources, ManifestSource{
			SessionID: st.SessionID,
			Agent:     run.Name,
			Label:     labelForReviewAgent(run.Name),
			Status:    run.Status.String(),
			Output:    agentRunOutput(run),
		})
	}
	return manifest
}

func localReviewManifestFromCurrentState(
	ctx context.Context,
	worktreeRoot string,
	headSHA string,
	summary reviewtypes.RunSummary,
	aggregateOutput string,
) (LocalReviewManifest, []*session.State, error) {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return LocalReviewManifest{}, nil, fmt.Errorf("create session state store: %w", err)
	}
	states, err := store.List(ctx)
	if err != nil {
		return LocalReviewManifest{}, nil, fmt.Errorf("list session states: %w", err)
	}
	return buildLocalReviewManifestFromSummary(worktreeRoot, headSHA, summary, states, aggregateOutput), states, nil
}

