		}
		loc := f.File
		if f.Line > 0 {
			loc = fmt.Sprintf("%s:%d", f.File, f.Line)
		}
		status := ""
		if i < len(m.fixStatus) && m.fixStatus[i] != "" {
			status = "  " + fixStatusLabel(m.fixStatus[i])
		}
		lines = append(lines, fmt.Sprintf("%s%s %-6s %-22s %s  %s %s%s",
			cursor, sel, strings.ToUpper(string(f.Severity)), loc, f.Title, confidenceDots(f.Confidence), f.Agent, status))
		lines = append(lines, m.findingSubLines(i, f)...)
	}
	return lines
}

// findingSubLines renders the indented sub-line(s) under a finding. After a fix
// it shows the semantic result on one line and the touched files + ± counts +
// diff hint on a SECOND line (so a long summary can't truncate the file/count
// metadata off the right edge). Before a fix it shows, for the focused finding
// only, a "what would change" preview from the reviewer's suggestion.
func (m reviewTUIModel) findingSubLines(i int, f Finding) []string {
	if i < len(m.fixStatus) && (m.fixStatus[i] == fixStatusFixed || m.fixStatus[i] == fixStatusNeedsHuman) {
		summary := "change applied"
		if i < len(m.fixSummary) {
			if s := strings.TrimSpace(m.fixSummary[i]); s != "" {
				summary = s
			}
		}
		out := []string{"      └ " + summary}
		if meta := m.fixMetaLine(i); meta != "" {
			out = append(out, "        "+meta)
		}
		return out
	}
	if i == m.findingIdx {
		if s := strings.TrimSpace(f.Suggestion); s != "" {
			target := ""
			if f.File != "" {
				target = " · " + f.File
			}
			return []string{"      ↪ would: " + s + target}
		}
	}
	return nil
}

// fixMetaLine renders the touched files + ± line counts + diff hint for finding
// i, e.g. "db.go, util.go · +5 −2   [o] diff". Empty when the fix changed
// nothing detectable (e.g. a no-op or failed edit).
func (m reviewTUIModel) fixMetaLine(i int) string {
	var parts []string
	if i < len(m.fixFiles) && len(m.fixFiles[i]) > 0 {
		parts = append(parts, strings.Join(m.fixFiles[i], ", "))
	}
	if i < len(m.fixAdded) && (m.fixAdded[i] > 0 || m.fixRemoved[i] > 0) {
		parts = append(parts, fmt.Sprintf("+%d −%d", m.fixAdded[i], m.fixRemoved[i]))
	}
	meta := strings.Join(parts, " · ")
	if i < len(m.fixDiff) && m.fixDiff[i] != "" {
		if meta != "" {
			meta += "   "
		}
		meta += "[o] diff"
	}
	return meta
}

// fixStatusLabel maps an apply status to its display label.
func fixStatusLabel(s string) string {
	switch s {
	case fixStatusFixing:
		return "⠼ fixing"
	case fixStatusFixed:
		return "fixed ✓"
	case fixStatusNeedsHuman:
		return "⚠ human"
	case fixStatusFailed:
		return "✗ failed"
	default:
		return s
	}
}

func (m reviewTUIModel) writeDashboardLine(b *strings.Builder, line string) {
	b.WriteString(truncateDisplayWidth(line, m.dashboardWidth()))
	b.WriteString("\n")
}

