func TestBuildFixCmd_AllowsHeadlessFileEditTools(t *testing.T) {
	t.Parallel()
	finding := review.Finding{
		Severity:   review.SeverityHigh,
		Title:      "missing guard",
		File:       "calc.go",
		Line:       12,
		Suggestion: "add the guard",
	}
	env := []string{
		"PATH=/bin",
		"ENTIRE_REVIEW_AGENT=claude-code",
		"ENTIRE_INVESTIGATE_SESSION=abc",
		"KEEP=1",
	}

	cmd := buildFixCmd(context.Background(), finding, "/repo", env)

	wantArgs := []string{
		"claude",
		"-p",
		review.ComposeFixPrompt(finding),
		"--allowedTools",
		"Read,Glob,Grep,Edit,MultiEdit,Write",
	}
