	}
	if slices.Contains(cmd.Env, "ENTIRE_INVESTIGATE_SESSION=abc") {
		t.Fatalf("Env retained investigate marker: %#v", cmd.Env)
	}
	if !slices.Contains(cmd.Env, "KEEP=1") || !slices.Contains(cmd.Env, "PATH=/bin") {
