// finding, it returns a tea.Cmd that runs the headless fixer on it and yields a
// fixOneDoneMsg with the semantic summary + diff + counts + re-verified status.
// The model drives the selected set through this one finding at a time, so each
// finding gets its own attributed diff. Returns nil when no fixer is available
// (Enter then just exits).
func buildApplyFunc(ctx context.Context, fixer Fixer, verifier VerifyProvider, worktreeRoot, scopeBaseRef string) func(Finding) tea.Cmd {
	if fixer == nil {
		return nil
	}
	return func(f Finding) tea.Cmd {
		return func() tea.Msg {
