// ComposeFixPrompt builds the single-finding fix instruction, including the
// SUMMARY contract the fixer must satisfy. Exported so per-agent fixers
// (claudecode) compose an identical prompt; the SUMMARY line is parsed back by
// ParseFixSummary.
func ComposeFixPrompt(f Finding) string {
	loc := f.File
	if f.Line > 0 {
		loc = fmt.Sprintf("%s:%d", f.File, f.Line)
	}
	var b strings.Builder
	b.WriteString("Fix this one review finding by editing the files directly. ")
	b.WriteString("Keep the change minimal and targeted — do not rewrite unrelated code.\n\n")
	fmt.Fprintf(&b, "[%s] %s (%s)\n", strings.ToUpper(string(f.Severity)), f.Title, loc)
	if f.Detail != "" {
		fmt.Fprintf(&b, "%s\n", f.Detail)
	}
	if f.Suggestion != "" {
		fmt.Fprintf(&b, "Suggested fix: %s\n", f.Suggestion)
	}
	b.WriteString("\nWhen done, end your reply with exactly one line:\n")
	b.WriteString("SUMMARY: <one sentence describing what you changed, naming the key snippet you added>\n")
	return b.String()
}

// ParseFixSummary extracts the trailing `SUMMARY:` line from a fixer's output.
// Returns "" when none is present (the model falls back to a generic label).
func ParseFixSummary(output string) string {
	lines := strings.Split(output, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if rest, ok := strings.CutPrefix(strings.TrimSpace(lines[i]), "SUMMARY:"); ok {
			return strings.TrimSpace(rest)
		}
	}
	return ""
}

// gitNumstat returns per-file (added, removed) line counts for the two-dot diff
// against base. Binary files (numstat "-") count as 0.
func gitNumstat(ctx context.Context, worktreeRoot, base string) map[string][2]int {
	res := map[string][2]int{}
	out, err := runGit(ctx, worktreeRoot, "diff", "--numstat", base)
	if err != nil {
		return res
	}
	for _, line := range strings.Split(out, "\n") {
		fields := strings.Split(line, "\t")
		if len(fields) < 3 {
			continue
		}
		res[fields[2]] = [2]int{atoiOrZero(fields[0]), atoiOrZero(fields[1])} // "-" (binary) → 0
