// atoiOrZero parses s, returning 0 on error (numstat uses "-" for binary files).
func atoiOrZero(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		return 0
	}
	return n
}

// numstatDelta returns the files whose counts changed between before and after,
// plus the total added/removed delta across them (clamped at 0).
func numstatDelta(before, after map[string][2]int) (files []string, added, removed int) {
	for f, a := range after {
		b := before[f]
		if a == b {
			continue
		}
		files = append(files, f)
		added += max(0, a[0]-b[0])
		removed += max(0, a[1]-b[1])
	}
	sort.Strings(files)
	return files, added, removed
}

// gitDiffFiles returns the two-dot diff against base restricted to files.
func gitDiffFiles(ctx context.Context, worktreeRoot, base string, files []string) string {
	out, err := runGit(ctx, worktreeRoot, append([]string{"diff", base, "--"}, files...)...)
	if err != nil {
		return ""
	}
	return out
}

